import { Plugin } from "@opencode/plugin/effect";
import { Tool } from "@opencode/schema/tool";
import { Effect } from "effect";
import { BINARY_EXTENSIONS, OFFICE_READ_EXTENSIONS, } from "../core/format/detect.js";
import { configureOptions } from "../core/options.js";
import { officecliInvokes } from "./invoke-names.js";
import { editTool } from "./tools/edit.js";
import { officecliTool } from "./tools/officecli.js";
export const isBlockedTool = (tool) => tool === "edit" || tool === "write";
const blockMessage = "use officecli tool for office/PDF files — office is the main method for read + handle";
export const blockBinary = (tool, input) => {
    const args = (input ?? {});
    let fp = "";
    if (typeof args.filePath === "string") {
        fp = args.filePath;
    }
    else if (typeof args.path === "string") {
        fp = args.path;
    }
    const ext = fp.includes(".")
        ? fp.slice(fp.lastIndexOf(".")).toLowerCase()
        : "";
    if ((isBlockedTool(tool) && BINARY_EXTENSIONS.has(ext)) ||
        (tool === "read" && OFFICE_READ_EXTENSIONS.has(ext))) {
        throw new Tool.Error({ message: blockMessage });
    }
};
export const OpenOfficePlugin = Plugin.define({
    effect: (rawCtx) => Effect.gen(function* effect() {
        const ctx = rawCtx;
        configureOptions(ctx.options);
        if (ctx.invoke) {
            for (const name of Object.keys(officecliInvokes)) {
                yield* ctx.invoke.register(name, (input) => Effect.tryPromise({
                    catch: (error) => error instanceof Error ? error : new Error(String(error)),
                    try: async () => {
                        const { runOfficecliInvoke } = await import("./host.js");
                        return runOfficecliInvoke(name, input);
                    },
                }));
            }
        }
        if (ctx.tool) {
            // add(editTool) replaces the builtin edit by name (ADR 0010) — draft lifecycle covers every write
            yield* ctx.tool.transform((editor) => {
                editor.add(officecliTool);
                editor.add(editTool);
            });
            // ponytail: host runs hook callbacks through yield* — the non-throwing path must return an Effect, not undefined
            yield* ctx.tool.hook("execute.before", (event) => {
                blockBinary(event.tool, event.input);
                return Effect.void;
            });
        }
        yield* Effect.addFinalizer(() => Effect.promise(async () => {
            const { listActiveDrafts } = await import("../core/draft/manager.js");
            for (const draft of listActiveDrafts()) {
                if (draft.orphaned) {
                    console.log(`[office-plugin] Orphaned draft: ${draft.filePath}`);
                }
            }
        }).pipe(Effect.ignore));
    }),
    id: "openoffice",
});
export default OpenOfficePlugin;
