import { readFileSync, writeFileSync, existsSync, readdirSync, statSync, mkdirSync, } from "node:fs";
// Draft lifecycle module: the only Draft surface the plugin layer may import.
// Owns hashing, locks, Registry registration, Sidecars, snapshots, and the
// draft-file IO. Callers state intent + session identity; the hash/lock
// preamble lives exactly once, here.
import nodePath from "node:path";
import { readMetadata } from "../format/metadata.js";
import { readRealFileAsMarkdown } from "../format/read.js";
import { getDraftsDir, getFilePathHash } from "../storage/paths.js";
import { registerDraft } from "../storage/registry.js";
import { substituteOoxml } from "../template/substitute-ooxml.js";
import * as lock from "./lock";
import { createDraft, acceptDraft, undoDraft, draftExists, getHistory, getSnapshot, getSnapshotSidecar, listActiveDrafts, getDraftSessions, } from "./manager";
import { readSidecar, writeSidecar } from "./sidecar";
export class DraftError extends Error {
    name = "DraftError";
}
export const hashOf = (filePath) => getFilePathHash(filePath);
export const draftPath = (filePath, sessionID) => nodePath.join(getDraftsDir(), getFilePathHash(filePath), `${sessionID}${nodePath.extname(filePath)}`);
export const exists = (filePath, sessionID) => draftExists(getFilePathHash(filePath), sessionID);
export const draftSessions = (filePath) => getDraftSessions(getFilePathHash(filePath));
export const mostRecentDraftSession = (filePath) => {
    const dir = nodePath.join(getDraftsDir(), getFilePathHash(filePath));
    if (!existsSync(dir)) {
        return undefined;
    }
    const entries = readdirSync(dir).map((file) => {
        const e = nodePath.extname(file);
        return {
            mtime: statSync(nodePath.join(dir, file)).mtimeMs,
            session: e ? file.slice(0, -e.length) : file,
        };
    });
    if (entries.length === 0) {
        return undefined;
    }
    let [latest] = entries;
    for (const entry of entries.slice(1)) {
        if (entry.mtime >= latest.mtime) {
            latest = entry;
        }
    }
    return latest.session;
};
export const requireOwned = (filePath, sessionID, message) => {
    const l = lock.getLock(getFilePathHash(filePath));
    if (!l || l.sessionID !== sessionID) {
        throw new DraftError(message);
    }
};
export const requireDraftExists = (filePath, sessionID, message = "draft not found") => {
    if (!exists(filePath, sessionID)) {
        throw new DraftError(message);
    }
};
export const assertNoForeignLock = (filePath, sessionID, allowStale, label = filePath) => {
    const hash = getFilePathHash(filePath);
    const l = lock.getLock(hash);
    if (l &&
        l.sessionID !== sessionID &&
        (!allowStale || !lock.isLockStale(hash))) {
        throw new DraftError(`lock on ${label} held by session ${l.sessionID}`);
    }
};
export const create = (filePath, sessionID, owner, content) => {
    lock.acquireLock(getFilePathHash(filePath), sessionID, owner);
    createDraft(filePath, sessionID, content);
};
export const write = (filePath, sessionID, content) => {
    writeFileSync(draftPath(filePath, sessionID), content);
};
// ponytail: comment/track drafts hold real OOXML — sniff PK, extract text, never dump zip bytes
export const draftMarkdown = (filePath, sessionID) => {
    const path = draftPath(filePath, sessionID);
    const buf = readFileSync(path);
    const isZip = buf.length >= 2 && buf[0] === 0x50 && buf[1] === 0x4b;
    if (isZip) {
        return readRealFileAsMarkdown(path);
    }
    return Promise.resolve(buf.toString("utf-8"));
};
export const cloneIntoDraft = (filePath, sessionID, owner, buffer) => {
    const hash = getFilePathHash(filePath);
    lock.acquireLock(hash, sessionID, owner);
    const target = nodePath.join(getDraftsDir(), hash, `${sessionID}${nodePath.extname(filePath)}`);
    mkdirSync(nodePath.dirname(target), { recursive: true });
    writeFileSync(target, buffer);
    registerDraft(filePath);
};
export const accept = async (filePath, sessionID, timestamp) => {
    await acceptDraft(filePath, sessionID, timestamp);
};
// L3 Fidelity substitute: run-preserving {{placeholder}} replace on a Draft ZIP.
export const substituteInDraft = async (filePath, sessionID, data) => {
    const path = draftPath(filePath, sessionID);
    const buf = readFileSync(path);
    const isZip = buf.length >= 2 && buf[0] === 0x50 && buf[1] === 0x4b;
    if (!isZip) {
        throw new DraftError("substitute only supported on OOXML drafts (clone first for L3)");
    }
    const { buffer, replaced, format } = await substituteOoxml(buf, data);
    writeFileSync(path, buffer);
    return { format, replaced };
