export const history = (filePath) => getHistory(getFilePathHash(filePath)).map((ap) => ({
    sessionID: ap.sessionID,
    timestamp: ap.timestamp,
}));
export const listDrafts = (filterPath) => {
    if (!filterPath) {
        return listActiveDrafts();
    }
    return listActiveDrafts().filter((d) => d.filePath === filterPath ||
        nodePath.resolve(d.filePath) === nodePath.resolve(filterPath));
};
export const status = (filePath) => {
    const hash = getFilePathHash(filePath);
    const l = lock.getLock(hash);
    if (!l) {
        return null;
    }
    return {
        owner: l.owner,
        sessionID: l.sessionID,
        stale: lock.isLockStale(hash),
        status: l.status,
        touchedAt: l.touchedAt,
    };
};
export const lockSession = (filePath) => lock.getLock(getFilePathHash(filePath))?.sessionID ?? null;
export const forceRelease = (filePath, sessionID, owner) => {
    const hash = getFilePathHash(filePath);
    if (!lock.getLock(hash)) {
        throw new DraftError(`no lock on ${filePath} to force release`);
    }
    if (!lock.isLockStale(hash)) {
        throw new DraftError(`lock on ${filePath} is not stale; force release allowed only on stale locks`);
    }
    lock.overrideLock(hash, sessionID, owner);
